impl Solution {
  pub fn calculate(s: String) -> i32 {
    let b = s.as_bytes();
    let n = b.len();
    let (mut result, mut prev, mut cur) = (0i64, 0i64, 0i64);
    let mut op = b'+';
    for i in 0..=n {
      if i < n && b[i].is_ascii_digit() {
        cur = cur * 10 + (b[i] - b'0') as i64;
      } else if i == n || b[i] != b' ' {
        match op {
          b'+' => {
            result += prev;
            prev = cur;
          }
          b'-' => {
            result += prev;
            prev = -cur;
          }
          b'*' => prev *= cur,
          b'/' => prev /= cur,
          _ => {}
        }
        if i < n {
          op = b[i];
        }
        cur = 0;
      }
    }
    (result + prev) as i32
  }
}

const calculate = (s: string): number => {
  let result = 0;
  let prev = 0;
  let cur = 0;
  let op = '+';
  const n = s.length;
  for (let i = 0; i <= n; i++) {
    if (i < n && s[i] >= '0' && s[i] <= '9') {
      cur = cur * 10 + (s.charCodeAt(i) - 48);
    } else if (i === n || s[i] !== ' ') {
      if (op === '+') {
        result += prev;
        prev = cur;
      } else if (op === '-') {
        result += prev;
        prev = -cur;
      } else if (op === '*') {
        prev *= cur;
      } else if (op === '/') {
